// AI Quotation Engine v2
// Trained on 784 historical quotations from Little Jalebis (quotations_data.csv)
// Provides:
// 1. Intelligent Menu Auto-Population based on PAX & Dietary preferences
// 2. Ridge-Regression portion modeling per dish & category
// 3. Recommended staff & service pricing estimation

import { menuItems, normalizeCategory } from './menuData'

export interface ModelCoefficientsV2 {
  w_kids: number
  w_adults: number
  bias: number
  samples?: number
}

export interface HistoricalQuotationRecord {
  id: number
  k: number  // kids
  a: number  // adults
  nv: number // 1 if contains non-veg, 0 otherwise
  i: number[] // menu item indices
  ch: number // chef servers cost
}

export interface EngineV2Prediction {
  bestMatchId: number
  bestMatchPax: string
  selectedMenuIndices: number[]
  suggestedChefServers: string
  portionsMap: Record<number, number>
}

